import { nodeResolve } from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';
import typescript from 'rollup-plugin-typescript-paths';

export default {
  input: 'src/index.ts',
  output: {
    file: 'dist/plugin.cjs.js',
    format: 'cjs',
    sourcemap: true,
    exports: 'named',
  },
  external: ['@capacitor/core'],
  plugins: [
    typescript({
      tsconfigPath: './tsconfig.json',
    }),
    nodeResolve({
      extensions: ['.js', '.ts'],
    }),
    commonjs({
      extensions: ['.ts', '.js'],
    }),
  ],
};

export interface EchoOptions {
  value: string;
}

export interface EchoResult {
  value: string;
}

export interface ReverseOptions {
  value: string;
}

export interface ReverseResult {
  value: string;
}

export interface SlugifyOptions {
  value: string;
}

export interface SlugifyResult {
  slug: string;
}

/**
 * The `StringKit` plugin interface.
 */
export interface StringKitPlugin {
  /**
   * Returns the input `value` unchanged.
   */
  echo(options: EchoOptions): Promise<EchoResult>;

  /**
   * Returns the input `value` reversed.
   */
  reverse(options: ReverseOptions): Promise<ReverseResult>;

  /**
   * Returns a URL-safe slug of the input `value`.
   */
  slugify(options: SlugifyOptions): Promise<SlugifyResult>;
}

import { WebPlugin } from '@capacitor/core';

import type {
  EchoOptions,
  EchoResult,
  ReverseOptions,
  ReverseResult,
  SlugifyOptions,
  SlugifyResult,
  StringKitPlugin,
} from './definitions';

/**
 * Web implementation of the {@link StringKitPlugin}.
 */
export class StringKitWeb
  extends WebPlugin
  implements StringKitPlugin
{
  async echo(options: EchoOptions): Promise<EchoResult> {
    return { value: options.value };
  }

  async reverse(options: ReverseOptions): Promise<ReverseResult> {
    return { value: options.value.split('').reverse().join('') };
  }

  async slugify(options: SlugifyOptions): Promise<SlugifyResult> {
    const slug = options.value
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    return { slug };
  }
}

import { registerPlugin } from '@capacitor/core';

import type { StringKitPlugin } from './definitions';

export * from './definitions';

export const StringKit = registerPlugin<StringKitPlugin>('StringKit', {
  web: async () => {
    const { StringKitWeb } = await import('./web');
    return new StringKitWeb();
  },
});

import { nodeResolve } from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';

export default {
  input: 'dist/esm/index.js',
  output: {
    file: 'dist/plugin.cjs.js',
    format: 'cjs',
    sourcemap: true,
    exports: 'named',
  },
  external: ['@capacitor/core'],
  plugins: [
    nodeResolve({
      extensions: ['.js', '.ts'],
    }),
    commonjs({
      extensions: ['.ts', '.js'],
    }),
  ],
};

