(async () => {
  const echo = await StringKit.echo({ value: 'hello' });
  const rev = await StringKit.reverse({ value: 'abcde' });
  const slug = await StringKit.slugify({ value: '  Hello, World! 123 ' });
  console.log('echo:', echo);
  console.log('reverse:', rev);
  console.log('slugify:', slug);
  console.assert(echo.value === 'hello', 'echo failed');
  console.assert(rev.value === 'edcba', 'reverse failed');
  console.assert(slug.slug === 'hello-world-123', 'slugify failed');
  console.log('ALL CJS TESTS PASSED');
})();
"

